import re,difflib
spec=open('PRODUCT_SPEC.md').read()
base=open('skills/live-spec-base/SKILL.md').read().split('\n')
# rule bodies
import re
def rule(n):
    s=[i for i,l in enumerate(base) if re.match(rf'^{n}\. \*\*',l)]
    if not s: return ''
    st=s[0]
    for j in range(st+1,len(base)):
        if re.match(r'^\d+\. \*\*',base[j]) or base[j].startswith('## '): break
    return ' '.join(base[st:j])
# spec criterion lines by anchor
crit={}
for m in re.finditer(r'^.*\[(INV|E|T|M|ACT)-(\d+)\].*$',spec,re.M):
    crit.setdefault(f"{m.group(1)}-{m.group(2)}",[]).append(m.group(0))
for n,a in [(20,'INV-65'),(21,'INV-84'),(22,'INV-98'),(28,'INV-145'),(32,'INV-217'),(35,'INV-302'),(25,'INV-137'),(33,'INV-237')]:
    r=rule(n)
    best=(0,'')
    for c in crit.get(a,[]):
        sc=difflib.SequenceMatcher(None,r.lower(),c.lower()).ratio()
        # also longest common substring
        m=difflib.SequenceMatcher(None,r,c).find_longest_match(0,len(r),0,len(c))
        if m.size>best[0]: best=(m.size,r[m.a:m.a+m.size],c[:90])
